// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(minSum <= type(uint256).max / 2);
        vm.assume(depositAmount <= type(uint256).max / 2);
        vm.assume(collectAmount <= depositAmount);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit funds from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);

        // Call Collect
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        if (success && balanceBefore >= minSum && balanceBefore >= collectAmount) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter <= balanceBefore);
        } else {
            // If Collect reverted or condition not met, balance should be unchanged
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

