pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 deposit, uint256 minSum, uint256 collectAmt) public {
        // Set up contract state
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Ensure caller has enough ether to deposit
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        // Record caller's balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Bound collectAmt to avoid overflow issues
        collectAmt = bound(collectAmt, 0, balanceBefore);

        // Call Collect
        c.Collect(collectAmt);

        // Check: Any address's balance should not exceed its previous balance + collectAmt
        // For simplicity, we check caller's balance
        uint256 balanceAfter = c.balances(caller);
        assertTrue(balanceAfter <= balanceBefore + collectAmt);
    }
}

