pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 initialBalance, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to avoid overflow and ensure sensible values
        vm.assume(initialBalance <= 1e30);
        vm.assume(depositAmount <= 1e30);
        vm.assume(collectAmount <= initialBalance + depositAmount);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Fund sender and make a deposit
        vm.deal(sender, initialBalance + depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // Record balances before Collect
        uint256 totalBefore = c.balances(sender);
        // Also sum other possible balances? Only sender matters as others are 0.
        // Assume only sender has nonzero balance; we check sender's balance afterward.

        // Call Collect
        uint256 collectValue = bound(collectAmount, 0, c.balances(sender));
        vm.prank(sender);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectValue));

        // Measure total balances after
        uint256 totalAfter = c.balances(sender);

        // Rule: total balances (only sender matters) should never increase
        assertTrue(totalAfter <= totalBefore);
    }
}

