pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound inputs to avoid overflow and ensure meaningful state
        vm.assume(caller != address(0));
        minSum = bound(minSum, 0, type(uint256).max / 2);
        depositAmount = bound(depositAmount, 0, type(uint256).max / 2);
        withdrawAmount = bound(withdrawAmount, 0, type(uint256).max / 2);
        vm.assume(depositAmount <= address(c).balance + 1e18); // avoid unrealistic deposits

        // Set up contract state
        c.SetMinSum(minSum);
        c.SetLogFile(address(0)); // dummy log address
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record caller's balance before Collect
        uint256 callerBalBefore = c.balances(caller);

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));
        if (!success) {
            // If revert, it must be because caller balance < minSum or < withdrawAmount
            assertTrue(callerBalBefore < minSum || callerBalBefore < withdrawAmount);
        } else {
            // If success, caller's balance must have decreased by exactly withdrawAmount
            // (The bug adds instead of subtracts, so the correct behavior is subtraction)
            uint256 callerBalAfter = c.balances(caller);
            assertTrue(callerBalAfter == callerBalBefore - withdrawAmount);
        }
    }
}

