        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        uint256 balanceAfter = c.balances(caller);

        // The general rule: balance should not increase after a Collect call (it should decrease or stay the same)
        // For the correct contract, balanceAfter <= balanceBefore (if Collect didn't revert)
        // For the buggy contract, balanceAfter becomes 0 (mutation: multiply by 0), so balanceAfter can be less than balanceBefore
