    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to avoid overflow and ensure valid state
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 1, 1e30);
        minSum = bound(minSum, 1, 1e30);
        collectAmount = bound(collectAmount, 1, 1e30);

