        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Ensure collectAmount <= deposited balance to satisfy the if condition
        vm.assume(collectAmount <= depositAmount && collectAmount >= minSum);

        uint256 balanceBefore = c.balances(caller);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        uint256 balanceAfter = c.balances(caller);
        // In the reference, if success, balance decreased by exactly collectAmount; if revert balance unchanged
        // But the bug multiplies by 0, so balanceAfter will be 0 if the call doesn't revert (and the if condition holds)
        // We assert that balanceAfter is either 0 (bug) or balanceBefore - collectAmount (reference) – but only reference is correct.
        // So a general rule: after a non-reverting Collect, balanceAfter == balanceBefore - collectAmount
        // However, to make it a single assertion that reference always passes and bug fails, we test the property when the Collect call succeeds.
        vm.assume(success);  // only consider successful Collect calls
        assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance after Collect must be old balance minus _am");
    }
}

