        c.Initialized();

        // Deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record total ether in system before collect
        uint256 totalBefore = address(c).balance;
        for (uint256 i = 0; i < 10; i++) {
            totalBefore += c.balances(address(uint160(i + 1)));
        }
        totalBefore += c.balances(caller);

        // Attempt collect
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Compute total after
        uint256 totalAfter = address(c).balance;
        for (uint256 i = 0; i < 10; i++) {
            totalAfter += c.balances(address(uint160(i + 1)));
        }
        totalAfter += c.balances(caller);

        // Invariant: total ether in the system (contract balance + all user balances) should equal deposited amount
        assertTrue(totalAfter == depositAmount, "Total ether in system changed");
