pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 withdrawAmount) public {
        // Bound inputs to realistic ranges
        minSum = bound(minSum, 0, 1e18);
        depositAmount = bound(depositAmount, 1e10, 1e18);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);
        vm.assume(caller != address(0) && caller != address(c));

        // Initialize contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0x1234));
        c.Initialized();

        // Deposit ether from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balances before Collect
        uint256 callerBalanceBefore = caller.balance;
        uint256 contractBalanceBefore = address(c).balance;
        uint256 callerCBalanceBefore = c.balances(caller);

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, withdrawAmount));

        // Only assert if call succeeded (no revert)
        if (success) {
            uint256 callerBalanceAfter = caller.balance;
            uint256 callerCBalanceAfter = c.balances(caller);
            // The caller's balance in the contract should decrease by withdrawAmount
            assertTrue(callerCBalanceAfter == callerCBalanceBefore - withdrawAmount, "Balance not decreased");
            // Also verify ether was transferred out: caller's ether balance increased by withdrawAmount
            assertTrue(callerBalanceAfter == callerBalanceBefore + withdrawAmount, "Ether not transferred");
            // Contract balance decreased by withdrawAmount
            assertTrue(address(c).balance == contractBalanceBefore - withdrawAmount, "Contract balance not decreased");
        }
    }
}

