pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        vm.assume(caller != address(0));
        minSum = bound(minSum, 0, 1e18);
        depositAmount = bound(depositAmount, 1, 1e18); // Must be > 0 to deposit
        collectAmount = bound(collectAmount, 0, depositAmount); // Must not exceed deposit

        // Initialize contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead)); // Dummy log file (address(0) is fine)
        c.Initialized();

        // Record initial total ETH in contract: user's balance + contract balance
        // (Before any interactions, contract balance is 0, user balance is 0)
        uint256 initialUserBalance = c.balances(caller);
        uint256 initialContractBalance = address(c).balance;
        uint256 initialTotal = initialUserBalance + initialContractBalance;

        // Deposit funds
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Update expected total after deposit: user balance increases by depositAmount, contract balance increases by depositAmount
        // So total = (initialUserBalance + depositAmount) + (initialContractBalance + depositAmount) = initialTotal + 2*depositAmount
        // But we only care about balance changes due to Collect, so we record state after deposit
        uint256 postDepositUserBalance = c.balances(caller);
        uint256 postDepositContractBalance = address(c).balance;
        uint256 totalAfterDeposit = postDepositUserBalance + postDepositContractBalance;

        // Call Collect
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        if (success) {
            // After successful Collect, the invariant: total (user balance + contract balance) remains same as after deposit
            uint256 finalUserBalance = c.balances(caller);
            uint256 finalContractBalance = address(c).balance;
            uint256 totalAfterCollect = finalUserBalance + finalContractBalance;
            assertTrue(totalAfterCollect == totalAfterDeposit, "Total ETH in contract invariant violated after Collect");
        } else {
            // If Collect reverted, nothing changed
            uint256 finalUserBalance = c.balances(caller);
            uint256 finalContractBalance = address(c).balance;
            uint256 totalAfterCollect = finalUserBalance + finalContractBalance;
            assertTrue(totalAfterCollect == totalAfterDeposit, "Total ETH in contract invariant violated after reverted Collect");
        }
    }
}

