        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 callerBalanceBefore = c.balances(caller);
        uint256 contractBalanceBefore = address(c).balance;
        uint256 sumBefore = callerBalanceBefore + contractBalanceBefore;

        // Attempt collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Only check invariant if collect succeeded
        vm.assume(success);

        uint256 callerBalanceAfter = c.balances(caller);
        uint256 contractBalanceAfter = address(c).balance;
        uint256 sumAfter = callerBalanceAfter + contractBalanceAfter;

        // The sum of caller's balance plus contract balance should remain the same
        assertTrue(sumBefore == sumAfter, "Sum invariant after successful Collect");
    }
}

