pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);

        // Set MinSum to 0 so Collect can succeed
        c.SetMinSum(0);
        c.Initialized();

        // Deposit into the contract
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);

        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        if (success) {
            uint256 balanceAfter = c.balances(caller);
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance should decrease by collect amount");
        }
    }
}
